import"./chunk-VC46IEJQ.js";var r={en:"Arms not described in the novels",zh:"\u5C0F\u8BF4\u4E2D\u672A\u63CF\u8FF0\u5176\u7EB9\u7AE0"},e=(o,n,a,s,t,i={})=>({id:o,name:{en:n,zh:a},...s,note:t,...i}),h={group:"vale",houses:[{id:"arryn",names:{en:"House Arryn",zh:"\u827E\u6797\u5BB6\u65CF"},region:"vale",seat:"the-eyrie",otherSeats:["gates-of-the-moon"],tier:"great",liege:null,sigil:{en:"A white crescent moon and falcon on a sky-blue field",zh:"\u5929\u84DD\u5E95\u4E0A\u7684\u767D\u8272\u65B0\u6708\u4E0E\u730E\u9E70"},colors:["#8fbfe0","#f4f3ee"],words:{en:"As High as Honor",zh:"\u9AD8\u5982\u8363\u8A89"},summary:{en:"Lords of the Eyrie and Defenders of the Vale, descended from Andal kings who once ruled the Mountain and Vale. Their line is among the oldest Andal blood in Westeros; they bent the knee to Aegon the Conqueror without a fight. Jon Arryn fostered Eddard Stark and Robert Baratheon and later served as King Robert's Hand.",zh:"\u9E70\u5DE2\u57CE\u7684\u9886\u4E3B\u3001\u8C37\u5730\u5B88\u62A4\uFF0C\u5176\u7956\u5148\u662F\u6614\u65E5\u7EDF\u6CBB\u201C\u5C71\u8109\u4E0E\u8C37\u5730\u201D\u7684\u5B89\u8FBE\u5C14\u738B\u65CF\u3002\u827E\u6797\u5BB6\u65CF\u662F\u7EF4\u65AF\u7279\u6D1B\u6700\u53E4\u8001\u7684\u5B89\u8FBE\u5C14\u8840\u8109\u4E4B\u4E00\uFF0C\u672A\u7ECF\u4E00\u6218\u4FBF\u5411\u5F81\u670D\u8005\u4F0A\u803F\u5C48\u819D\u3002\u743C\u6069\xB7\u827E\u6797\u66FE\u517B\u80B2\u827E\u5FB7\xB7\u53F2\u5854\u514B\u4E0E\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069\uFF0C\u540E\u6765\u51FA\u4EFB\u52B3\u52C3\u56FD\u738B\u7684\u9996\u76F8\u3002"},refs:["agot","asos","affc","twoiaf"],members:[e("jasper-arryn","Jasper Arryn","\u8D3E\u65AF\u5E15\xB7\u827E\u6797",{},{en:"Lord of the Eyrie before his son Jon.",zh:"\u743C\u6069\u4E4B\u524D\u7684\u9E70\u5DE2\u57CE\u516C\u7235\u3002"}),e("jon-arryn","Jon Arryn","\u743C\u6069\xB7\u827E\u6797",{father:"jasper-arryn",spouses:["jeyne-royce","rowena-arryn","lysa-tully"]},{en:"Lord of the Eyrie, Defender of the Vale and Warden of the East; foster-father of Eddard Stark and Robert Baratheon and Hand of King Robert. His sudden death sets the story in motion.",zh:"\u9E70\u5DE2\u57CE\u516C\u7235\u3001\u8C37\u5730\u5B88\u62A4\u3001\u4E1C\u5883\u5B88\u62A4\uFF1B\u827E\u5FB7\xB7\u53F2\u5854\u514B\u4E0E\u52B3\u52C3\xB7\u62DC\u62C9\u5E2D\u6069\u7684\u517B\u7236\uFF0C\u52B3\u52C3\u56FD\u738B\u7684\u9996\u76F8\u3002\u4ED6\u7684\u731D\u6B7B\u63ED\u5F00\u4E86\u6574\u4E2A\u6545\u4E8B\u7684\u5E8F\u5E55\u3002"},{fate:{en:"He was poisoned with the Tears of Lys by Lysa, at Petyr Baelish's urging (revealed in A Storm of Swords).",zh:"\u4ED6\u662F\u88AB\u83B1\u838E\u542C\u4ECE\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u7684\u5506\u4F7F\uFF0C\u7528\u201C\u91CC\u65AF\u4E4B\u6CEA\u201D\u6BD2\u6B7B\u7684\uFF08\u5377\u4E09\u63ED\u6653\uFF09\u3002"}}),e("ronnel-arryn","Ronnel Arryn","\u7F57\u5185\u5C14\xB7\u827E\u6797",{father:"jasper-arryn"},{en:"Younger brother of Jon Arryn.",zh:"\u743C\u6069\xB7\u827E\u6797\u7684\u5F1F\u5F1F\u3002"}),e("alys-arryn","Alys Arryn","\u827E\u4E3D\u4E1D\xB7\u827E\u6797",{father:"jasper-arryn"},{en:"Sister of Jon Arryn, wed to Ser Elys Waxley; through her line Harrold Hardyng later stands next in succession after Robert Arryn.",zh:"\u743C\u6069\xB7\u827E\u6797\u7684\u59B9\u59B9\uFF0C\u5AC1\u7ED9\u4F0A\u83B1\u65AF\xB7\u7EF4\u514B\u65AF\u5229\u7235\u58EB\uFF1B\u540E\u6765\u54C8\u7F57\u5FB7\xB7\u54C8\u4E01\u6B63\u662F\u51ED\u5979\u8FD9\u4E00\u652F\u8840\u8109\uFF0C\u6210\u4E3A\u4EC5\u6B21\u4E8E\u52B3\u52C3\xB7\u827E\u6797\u7684\u7EE7\u627F\u4EBA\u3002"}),e("rowena-arryn","Rowena Arryn","\u7F57\u7EF4\u5A1C\xB7\u827E\u6797",{spouses:["jon-arryn"]},{en:"A cousin of Jon Arryn and his second wife; she died without giving him a living child.",zh:"\u743C\u6069\xB7\u827E\u6797\u7684\u5802\u4EB2\u4E0E\u7B2C\u4E8C\u4EFB\u59BB\u5B50\uFF0C\u672A\u80FD\u4E3A\u4ED6\u7559\u4E0B\u5B58\u6D3B\u7684\u5B50\u55E3\u4FBF\u53BB\u4E16\u4E86\u3002"}),e("elbert-arryn","Elbert Arryn","\u827E\u5C14\u4F2F\u7279\xB7\u827E\u6797",{father:"ronnel-arryn"},{en:"Jon Arryn's nephew and heir, one of Brandon Stark's companions put to death by King Aerys II on the eve of Robert's Rebellion.",zh:"\u743C\u6069\xB7\u827E\u6797\u7684\u4F84\u5B50\u548C\u7EE7\u627F\u4EBA\uFF0C\u52B3\u52C3\u53DB\u4E71\u524D\u5915\u4E0E\u5E03\u5170\u767B\xB7\u53F2\u5854\u514B\u7684\u540C\u4F34\u4EEC\u4E00\u8D77\u88AB\u75AF\u738B\u4F0A\u91CC\u65AF\u4E8C\u4E16\u5904\u6B7B\u3002"}),e("robert-arryn","Robert Arryn","\u52B3\u52C3\xB7\u827E\u6797",{father:"jon-arryn",mother:"lysa-tully"},{en:`Jon and Lysa's only surviving child, a sickly, fit-prone boy who becomes Lord of the Eyrie on his father's death; called "Sweetrobin".`,zh:"\u743C\u6069\u4E0E\u83B1\u838E\u552F\u4E00\u5B58\u6D3B\u7684\u5B69\u5B50\uFF0C\u4F53\u5F31\u591A\u75C5\u3001\u65F6\u5E38\u62BD\u6410\uFF0C\u7236\u4EB2\u6B7B\u540E\u6210\u4E3A\u9E70\u5DE2\u57CE\u516C\u7235\uFF1B\u5C0F\u540D\u201C\u751C\u5FC3\u52B3\u52C3\u201D\u3002"})]},{id:"arryn-of-gulltown",names:{en:"House Arryn of Gulltown",zh:"\u6D77\u9E25\u9547\u7684\u827E\u6797\u5BB6\u65CF"},region:"vale",seat:"gulltown",tier:"minor",liege:"arryn",sigil:{en:"The Arryn moon-and-falcon, differenced for a cadet line",zh:"\u827E\u6797\u5BB6\u65CF\u7684\u65B0\u6708\u730E\u9E70\uFF0C\u52A0\u4EE5\u652F\u7CFB\u6807\u8BB0"},colors:["#8fbfe0","#f4f3ee"],summary:{en:"A cadet branch of the Arryns settled in Gulltown. Its best-remembered member, Ser Denys Arryn, was a celebrated young knight who died during the Greyjoy Rebellion, which left the main line's succession even narrower.",zh:"\u5B9A\u5C45\u6D77\u9E25\u9547\u7684\u827E\u6797\u5BB6\u65CF\u652F\u7CFB\u3002\u5176\u6700\u4E3A\u4EBA\u79F0\u9053\u7684\u6210\u5458\u6234\u5C3C\u65AF\xB7\u827E\u6797\u7235\u58EB\u662F\u4E00\u4F4D\u58F0\u540D\u8FDC\u626C\u7684\u9752\u5E74\u9A91\u58EB\uFF0C\u5728\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u4E2D\u9635\u4EA1\uFF0C\u4F7F\u827E\u6797\u4E3B\u652F\u7684\u7EE7\u627F\u4EBA\u9009\u6108\u53D1\u7A00\u5C11\u3002"},refs:["affc","twoiaf"],members:[e("denys-arryn","Denys Arryn","\u6234\u5C3C\u65AF\xB7\u827E\u6797",{},{en:"Dashing knight of the Gulltown Arryns, killed in the Greyjoy Rebellion.",zh:"\u6D77\u9E25\u9547\u827E\u6797\u652F\u7CFB\u7684\u98CE\u6D41\u9A91\u58EB\uFF0C\u6B7B\u4E8E\u845B\u96F7\u4E54\u4F0A\u53DB\u4E71\u3002"})]},{id:"royce",names:{en:"House Royce",zh:"\u7F57\u4F0A\u65AF\u5BB6\u65CF"},region:"vale",seat:"runestone",tier:"major",liege:"arryn",sigil:{en:"Black iron studs on bronze, within a border of black runes",zh:"\u9752\u94DC\u5E95\u4E0A\u6392\u5217\u9ED1\u94C1\u9489\uFF0C\u56DB\u5468\u73AF\u7ED5\u9ED1\u8272\u7B26\u6587"},colors:["#b08a4e","#1f1d1b"],words:{en:"We Remember",zh:"\u6211\u4EEC\u8BB0\u5F97"},summary:{en:'The proudest house of the Vale, of First Men blood and once kings there before the Andals came. Lord Yohn "Bronze Yohn" Royce wears ancient rune-carved bronze armour and is the natural leader of the Vale lords who distrust Petyr Baelish.',zh:"\u8C37\u5730\u6700\u9A84\u50B2\u7684\u5BB6\u65CF\uFF0C\u6D41\u7740\u5148\u6C11\u4E4B\u8840\uFF0C\u5728\u5B89\u8FBE\u5C14\u4EBA\u5230\u6765\u4E4B\u524D\u66FE\u662F\u8C37\u5730\u4E4B\u738B\u3002\u7EA6\u6069\xB7\u7F57\u4F0A\u65AF\u4F2F\u7235\u4EBA\u79F0\u201C\u9752\u94DC\u7EA6\u6069\u201D\uFF0C\u8EAB\u62AB\u523B\u6709\u7B26\u6587\u7684\u53E4\u8001\u9752\u94DC\u94E0\u7532\uFF0C\u662F\u4E0D\u4FE1\u4EFB\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u7684\u8C37\u5730\u8BF8\u4FAF\u7684\u5929\u7136\u9886\u8896\u3002"},refs:["agot","acok","affc","twoiaf"],members:[e("yohn-royce","Yohn Royce","\u7EA6\u6069\xB7\u7F57\u4F0A\u65AF",{},{en:"Lord of Runestone, called Bronze Yohn; a famed warrior and leader of the Lords Declarant.",zh:"\u7B26\u6587\u77F3\u57CE\u4F2F\u7235\uFF0C\u4EBA\u79F0\u201C\u9752\u94DC\u7EA6\u6069\u201D\uFF1B\u8457\u540D\u7684\u6218\u58EB\uFF0C\u7533\u8BC9\u8BF8\u4FAF\u7684\u9886\u8896\u3002"}),e("jeyne-royce","Jeyne Royce","\u73CD\u59AE\xB7\u7F57\u4F0A\u65AF",{spouses:["jon-arryn"]},{en:"Jon Arryn's first wife; she died young and left no surviving children.",zh:"\u743C\u6069\xB7\u827E\u6797\u7684\u7B2C\u4E00\u4EFB\u59BB\u5B50\uFF0C\u65E9\u901D\uFF0C\u672A\u7559\u4E0B\u5B58\u6D3B\u7684\u5B50\u55E3\u3002"}),e("andar-royce","Andar Royce","\u5B89\u8FBE\xB7\u7F57\u4F0A\u65AF",{father:"yohn-royce"},{en:"Eldest son and heir of Lord Yohn.",zh:"\u7EA6\u6069\u4F2F\u7235\u7684\u957F\u5B50\u548C\u7EE7\u627F\u4EBA\u3002"}),e("robar-royce","Robar Royce","\u7F57\u62D4\xB7\u7F57\u4F0A\u65AF",{father:"yohn-royce"},{en:"A tourney champion who joined Renly Baratheon's Rainbow Guard.",zh:"\u6BD4\u6B66\u5927\u4F1A\u7684\u5E38\u80DC\u8005\uFF0C\u52A0\u5165\u4E86\u84DD\u793C\xB7\u62DC\u62C9\u5E2D\u6069\u7684\u5F69\u8679\u62A4\u536B\u3002"},{fate:{en:"Slain by Ser Loras Tyrell in his grief over Renly's murder (A Clash of Kings).",zh:"\u84DD\u793C\u9047\u5BB3\u540E\uFF0C\u60B2\u6124\u7684\u6D1B\u62C9\u65AF\xB7\u63D0\u5229\u5C14\u7235\u58EB\u5C06\u4ED6\u6740\u6B7B\uFF08\u5377\u4E8C\uFF09\u3002"}}),e("waymar-royce","Waymar Royce","\u5A01\u739B\xB7\u7F57\u4F0A\u65AF",{father:"yohn-royce"},{en:"Lord Yohn's youngest son, a new ranger of the Night's Watch.",zh:"\u7EA6\u6069\u4F2F\u7235\u7684\u5E7C\u5B50\uFF0C\u5B88\u591C\u4EBA\u4E2D\u65B0\u664B\u7684\u6E38\u9A91\u5175\u3002"},{fate:{en:"Killed by the Others beyond the Wall in the prologue of A Game of Thrones, and rises again as a wight.",zh:"\u5728\u5377\u4E00\u5E8F\u7AE0\u4E2D\u4E8E\u957F\u57CE\u4EE5\u5317\u88AB\u5F02\u9B3C\u6740\u5BB3\uFF0C\u968F\u540E\u5316\u4E3A\u5C38\u9B3C\u518D\u5EA6\u8D77\u8EAB\u3002"}})]},{id:"royce-gates-of-the-moon",names:{en:"House Royce of the Gates of the Moon",zh:"\u6708\u95E8\u5821\u7684\u7F57\u4F0A\u65AF\u5BB6\u65CF"},region:"vale",seat:"gates-of-the-moon",tier:"minor",liege:"arryn",sigil:{en:"The Royce studs and runes, differenced for a cadet line",zh:"\u7F57\u4F0A\u65AF\u5BB6\u65CF\u7684\u94C1\u9489\u4E0E\u7B26\u6587\uFF0C\u52A0\u4EE5\u652F\u7CFB\u6807\u8BB0"},colors:["#b08a4e","#1f1d1b"],summary:{en:"The junior branch of the Royces, who keep the Gates of the Moon for the Arryns. Ser Nestor Royce, High Steward of the Vale, is a cousin of Bronze Yohn but far more willing to serve whoever holds the Eyrie.",zh:"\u7F57\u4F0A\u65AF\u5BB6\u65CF\u7684\u6B21\u652F\uFF0C\u4EE3\u827E\u6797\u5BB6\u65CF\u9547\u5B88\u6708\u95E8\u5821\u3002\u8C37\u5730\u603B\u7BA1\u5948\u65AF\u7279\xB7\u7F57\u4F0A\u65AF\u7235\u58EB\u662F\u9752\u94DC\u7EA6\u6069\u7684\u5802\u4EB2\uFF0C\u4F46\u8FDC\u6BD4\u540E\u8005\u66F4\u613F\u610F\u6548\u529B\u4E8E\u9E70\u5DE2\u57CE\u7684\u5F53\u6743\u8005\u3002"},refs:["agot","affc"],members:[e("nestor-royce","Nestor Royce","\u5948\u65AF\u7279\xB7\u7F57\u4F0A\u65AF",{},{en:"High Steward of the Vale and castellan of the Gates of the Moon.",zh:"\u8C37\u5730\u603B\u7BA1\uFF0C\u6708\u95E8\u5821\u4EE3\u7406\u57CE\u4E3B\u3002"},{fate:{en:"Petyr Baelish grants him the Gates of the Moon as a hereditary seat, binding him to Petyr's side (A Feast for Crows).",zh:"\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u628A\u6708\u95E8\u5821\u8D50\u7ED9\u4ED6\u4F5C\u4E3A\u4E16\u88AD\u9886\u5730\uFF0C\u4ECE\u800C\u5C06\u4ED6\u62C9\u5230\u81EA\u5DF1\u4E00\u8FB9\uFF08\u5377\u56DB\uFF09\u3002"}}),e("albar-royce","Albar Royce","\u827E\u5DF4\xB7\u7F57\u4F0A\u65AF",{father:"nestor-royce"},{en:"Ser Nestor's son and heir.",zh:"\u5948\u65AF\u7279\u7235\u58EB\u4E4B\u5B50\u4E0E\u7EE7\u627F\u4EBA\u3002"}),e("myranda-royce","Myranda Royce","\u7C73\u5170\u8FBE\xB7\u7F57\u4F0A\u65AF",{father:"nestor-royce"},{en:"Ser Nestor's lively, gossiping daughter, called Randa.",zh:"\u5948\u65AF\u7279\u7235\u58EB\u6D3B\u6CFC\u7231\u8BF4\u95F2\u8BDD\u7684\u5973\u513F\uFF0C\u6635\u79F0\u201C\u5170\u8FBE\u201D\u3002"})]},{id:"waynwood",names:{en:"House Waynwood",zh:"\u97E6\u4F0D\u5FB7\u5BB6\u65CF"},region:"vale",seat:"ironoaks",tier:"major",liege:"arryn",sigil:{en:"A broken wheel, black on green",zh:"\u7EFF\u5E95\u4E0A\u7684\u9ED1\u8272\u65AD\u8F6E"},colors:["#3f6b3a","#1f1d1b"],summary:{en:"An old Andal house of the Vale, ruled in the books by the shrewd Lady Anya Waynwood. Her son Ser Donnel holds the Bloody Gate as Knight of the Gate, and she fosters Harrold Hardyng.",zh:"\u8C37\u5730\u53E4\u8001\u7684\u5B89\u8FBE\u5C14\u5BB6\u65CF\uFF0C\u4E66\u4E2D\u7531\u7CBE\u660E\u7684\u5B89\u96C5\xB7\u97E6\u4F0D\u5FB7\u592B\u4EBA\u5F53\u5BB6\u3002\u5979\u7684\u513F\u5B50\u5510\u7EB3\u7235\u58EB\u4EE5\u201C\u8840\u95E8\u9A91\u58EB\u201D\u7684\u8EAB\u4EFD\u9547\u5B88\u8840\u95E8\uFF0C\u5979\u8FD8\u6536\u517B\u7740\u54C8\u7F57\u5FB7\xB7\u54C8\u4E01\u3002"},refs:["agot","affc","twoiaf"],members:[e("anya-waynwood","Anya Waynwood","\u5B89\u96C5\xB7\u97E6\u4F0D\u5FB7",{},{en:"Lady of Ironoaks, one of the most respected of the Lords Declarant.",zh:"\u94C1\u6A61\u5821\u5973\u4F2F\u7235\uFF0C\u7533\u8BC9\u8BF8\u4FAF\u4E2D\u6700\u53D7\u656C\u91CD\u7684\u4EBA\u7269\u4E4B\u4E00\u3002"}),e("morton-waynwood","Morton Waynwood","\u83AB\u987F\xB7\u97E6\u4F0D\u5FB7",{mother:"anya-waynwood"},{en:"Lady Anya's eldest son and heir.",zh:"\u5B89\u96C5\u592B\u4EBA\u7684\u957F\u5B50\u548C\u7EE7\u627F\u4EBA\u3002"}),e("donnel-waynwood","Donnel Waynwood","\u5510\u7EB3\xB7\u97E6\u4F0D\u5FB7",{mother:"anya-waynwood"},{en:"Knight of the Gate, commanding the Bloody Gate; he meets Catelyn Stark when she arrives in the Vale.",zh:"\u201C\u8840\u95E8\u9A91\u58EB\u201D\uFF0C\u7EDF\u9886\u8840\u95E8\u5B88\u519B\uFF1B\u51EF\u7279\u7433\xB7\u53F2\u5854\u514B\u62B5\u8FBE\u8C37\u5730\u65F6\u7531\u4ED6\u8FCE\u63A5\u3002"}),e("wallace-waynwood","Wallace Waynwood","\u534E\u83B1\u58EB\xB7\u97E6\u4F0D\u5FB7",{mother:"anya-waynwood"},{en:"A younger son of Lady Anya.",zh:"\u5B89\u96C5\u592B\u4EBA\u7684\u5E7C\u5B50\u4E4B\u4E00\u3002"})]},{id:"corbray",names:{en:"House Corbray",zh:"\u79D1\u5E03\u745E\u5BB6\u65CF"},region:"vale",seat:"hearts-home",tier:"major",liege:"arryn",sigil:{en:"Three black ravens on white, each holding a red heart",zh:"\u767D\u5E95\u4E0A\u4E09\u53EA\u9ED1\u8272\u6E21\u9E26\uFF0C\u5404\u8854\u4E00\u9897\u7EA2\u5FC3"},colors:["#f1efe8","#1f1d1b"],summary:{en:"An ancient Vale house whose treasure is the Valyrian steel longsword Lady Forlorn. Lord Lyonel Corbray rules Heart's Home, while his brother Ser Lyn is a dangerous swordsman with a grudge against Petyr Baelish.",zh:"\u8C37\u5730\u7684\u53E4\u8001\u5BB6\u65CF\uFF0C\u4F20\u5BB6\u4E4B\u5B9D\u662F\u74E6\u96F7\u5229\u4E9A\u94A2\u957F\u5251\u201C\u5B64\u5973\u201D\u3002\u83B1\u6602\u8BFA\xB7\u79D1\u5E03\u745E\u4F2F\u7235\u7EDF\u6CBB\u5FC3\u4E4B\u5BB6\uFF0C\u4ED6\u7684\u5F1F\u5F1F\u6797\u6069\u7235\u58EB\u5219\u662F\u5371\u9669\u7684\u5251\u5BA2\uFF0C\u4E0E\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u79EF\u6028\u9887\u6DF1\u3002"},refs:["agot","affc","twoiaf"],members:[e("lyonel-corbray","Lyonel Corbray","\u83B1\u6602\u8BFA\xB7\u79D1\u5E03\u745E",{},{en:"Lord of Heart's Home.",zh:"\u5FC3\u4E4B\u5BB6\u4F2F\u7235\u3002"}),e("lyn-corbray","Lyn Corbray","\u6797\u6069\xB7\u79D1\u5E03\u745E",{},{en:"Lord Lyonel's younger brother, a famed and cruel swordsman who bears Lady Forlorn.",zh:"\u83B1\u6602\u8BFA\u4F2F\u7235\u4E4B\u5F1F\uFF0C\u4F69\u5E26\u201C\u5B64\u5973\u201D\u7684\u8457\u540D\u5251\u5BA2\uFF0C\u751F\u6027\u6B8B\u5FCD\u3002"}),e("lucas-corbray","Lucas Corbray","\u5362\u5361\u65AF\xB7\u79D1\u5E03\u745E",{},{en:"The youngest Corbray brother.",zh:"\u79D1\u5E03\u745E\u4E09\u5144\u5F1F\u4E2D\u6700\u5C0F\u7684\u4E00\u4E2A\u3002"})]},{id:"redfort",names:{en:"House Redfort",zh:"\u96F7\u5FB7\u4F5B\u5BB6\u65CF"},region:"vale",seat:"redfort",tier:"major",liege:"arryn",sigil:{en:"A red castle",zh:"\u4E00\u5EA7\u7EA2\u8272\u57CE\u5821"},colors:["#d8d2c4","#a3332b"],summary:{en:"An old Andal house of the southern Vale. Lord Horton Redfort is one of the Lords Declarant, and his sons are knights in the Vale's host.",zh:"\u8C37\u5730\u5357\u90E8\u7684\u53E4\u8001\u5B89\u8FBE\u5C14\u5BB6\u65CF\u3002\u970D\u987F\xB7\u96F7\u5FB7\u4F5B\u4F2F\u7235\u662F\u7533\u8BC9\u8BF8\u4FAF\u4E4B\u4E00\uFF0C\u4ED6\u7684\u51E0\u4E2A\u513F\u5B50\u90FD\u662F\u8C37\u5730\u519B\u4E2D\u7684\u9A91\u58EB\u3002"},refs:["agot","affc","twoiaf"],members:[e("horton-redfort","Horton Redfort","\u970D\u987F\xB7\u96F7\u5FB7\u4F5B",{},{en:"Lord of Redfort and one of the Lords Declarant.",zh:"\u96F7\u5FB7\u4F5B\u57CE\u4F2F\u7235\uFF0C\u7533\u8BC9\u8BF8\u4FAF\u4E4B\u4E00\u3002"}),e("jasper-redfort","Jasper Redfort","\u8D3E\u65AF\u5E15\xB7\u96F7\u5FB7\u4F5B",{father:"horton-redfort"},{en:"Son of Lord Horton.",zh:"\u970D\u987F\u4F2F\u7235\u4E4B\u5B50\u3002"}),e("creighton-redfort","Creighton Redfort","\u514B\u83B1\u987F\xB7\u96F7\u5FB7\u4F5B",{father:"horton-redfort"},{en:"Son of Lord Horton.",zh:"\u970D\u987F\u4F2F\u7235\u4E4B\u5B50\u3002"}),e("mychel-redfort","Mychel Redfort","\u7C73\u6B47\u5C14\xB7\u96F7\u5FB7\u4F5B",{father:"horton-redfort"},{en:"Lord Horton's youngest son, once squire to Ser Lyn Corbray.",zh:"\u970D\u987F\u4F2F\u7235\u7684\u5E7C\u5B50\uFF0C\u66FE\u4EFB\u6797\u6069\xB7\u79D1\u5E03\u745E\u7235\u58EB\u7684\u4F8D\u4ECE\u3002"})]},{id:"hunter",names:{en:"House Hunter",zh:"\u4EA8\u7279\u5BB6\u65CF"},region:"vale",seat:"longbow-hall",tier:"major",liege:"arryn",sigil:{en:"Five silver arrows fanned on brown",zh:"\u8910\u5E95\u4E0A\u5448\u6247\u5F62\u6392\u5217\u7684\u4E94\u652F\u94F6\u7BAD"},colors:["#6b4a2e","#d9d9d6"],summary:{en:"Lords of Longbow Hall in the north-eastern Vale. Old Lord Eon Hunter outlived most of his rivals, and his three sons quarrel bitterly over his inheritance.",zh:"\u8C37\u5730\u4E1C\u5317\u90E8\u957F\u5F13\u5385\u7684\u9886\u4E3B\u3002\u8001\u9886\u4E3B\u4F0A\u6602\xB7\u4EA8\u7279\u71AC\u8FC7\u4E86\u5927\u591A\u6570\u5BF9\u624B\uFF0C\u800C\u4ED6\u7684\u4E09\u4E2A\u513F\u5B50\u4E3A\u4E89\u593A\u9057\u4EA7\u5435\u5F97\u4E0D\u53EF\u5F00\u4EA4\u3002"},refs:["agot","affc"],members:[e("eon-hunter","Eon Hunter","\u4F0A\u6602\xB7\u4EA8\u7279",{},{en:"Aged Lord of Longbow Hall.",zh:"\u957F\u5F13\u5385\u5E74\u8FC8\u7684\u4F2F\u7235\u3002"},{fate:{en:"Dies before A Feast for Crows; his heir Gilwood is suspected of hastening his end.",zh:"\u5728\u5377\u56DB\u4E4B\u524D\u53BB\u4E16\uFF1B\u5176\u7EE7\u627F\u4EBA\u5409\u5C14\u4F0D\u5FB7\u88AB\u6000\u7591\u52A0\u901F\u4E86\u4ED6\u7684\u6B7B\u4EA1\u3002"}}),e("gilwood-hunter","Gilwood Hunter","\u5409\u5C14\u4F0D\u5FB7\xB7\u4EA8\u7279",{father:"eon-hunter"},{en:"Eldest son of Lord Eon, called Young Lord Hunter.",zh:"\u4F0A\u6602\u4F2F\u7235\u7684\u957F\u5B50\uFF0C\u4EBA\u79F0\u201C\u5C0F\u4EA8\u7279\u4F2F\u7235\u201D\u3002"}),e("eustace-hunter","Eustace Hunter","\u5C24\u65AF\u5854\u65AF\xB7\u4EA8\u7279",{father:"eon-hunter"},{en:"Son of Lord Eon.",zh:"\u4F0A\u6602\u4F2F\u7235\u4E4B\u5B50\u3002"}),e("harlan-hunter","Harlan Hunter","\u54C8\u5170\xB7\u4EA8\u7279",{father:"eon-hunter"},{en:"Son of Lord Eon.",zh:"\u4F0A\u6602\u4F2F\u7235\u4E4B\u5B50\u3002"})]},{id:"belmore",names:{en:"House Belmore",zh:"\u8D1D\u5C14\u6469\u5BB6\u65CF"},region:"vale",seat:"strongsong",tier:"major",liege:"arryn",sigil:{en:"Six silver bells on purple",zh:"\u7D2B\u5E95\u4E0A\u7684\u516D\u53EA\u94F6\u94C3"},colors:["#5a3a6e","#d9d9d6"],summary:{en:"Lords of Strongsong in the northern Vale. Lord Benedar Belmore joins the Lords Declarant against Petyr Baelish, though he is among the first to waver.",zh:"\u8C37\u5730\u5317\u90E8\u5F3A\u6B4C\u57CE\u7684\u9886\u4E3B\u3002\u73ED\u5C3C\u8FBE\xB7\u8D1D\u5C14\u6469\u4F2F\u7235\u52A0\u5165\u4E86\u53CD\u5BF9\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u7684\u7533\u8BC9\u8BF8\u4FAF\uFF0C\u5374\u4E5F\u662F\u6700\u65E9\u52A8\u6447\u7684\u4EBA\u4E4B\u4E00\u3002"},refs:["affc","twoiaf"],members:[e("benedar-belmore","Benedar Belmore","\u73ED\u5C3C\u8FBE\xB7\u8D1D\u5C14\u6469",{},{en:"Lord of Strongsong.",zh:"\u5F3A\u6B4C\u57CE\u4F2F\u7235\u3002"})]},{id:"templeton",names:{en:"House Templeton",zh:"\u5766\u5E15\u987F\u5BB6\u65CF"},region:"vale",seat:"ninestars",tier:"minor",liege:"arryn",sigil:{en:"Nine stars (exact blazon uncertain)",zh:"\u4E5D\u9897\u661F\uFF08\u5177\u4F53\u7EB9\u6837\u4E0D\u8BE6\uFF09"},colors:["#2f4f7f","#e8c95a"],summary:{en:"A Vale house whose head, Ser Symond Templeton, is styled the Knight of Ninestars. He sides with the Lords Declarant in A Feast for Crows.",zh:"\u8C37\u5730\u5BB6\u65CF\uFF0C\u65CF\u957F\u897F\u8499\xB7\u5766\u5E15\u987F\u7235\u58EB\u53F7\u79F0\u201C\u4E5D\u661F\u9A91\u58EB\u201D\u3002\u5728\u5377\u56DB\u4E2D\uFF0C\u4ED6\u7AD9\u5728\u7533\u8BC9\u8BF8\u4FAF\u4E00\u8FB9\u3002"},refs:["affc"],members:[e("symond-templeton","Symond Templeton","\u897F\u8499\xB7\u5766\u5E15\u987F",{},{en:"The Knight of Ninestars.",zh:"\u201C\u4E5D\u661F\u9A91\u58EB\u201D\u3002"})]},{id:"grafton",names:{en:"House Grafton",zh:"\u845B\u62C9\u592B\u987F\u5BB6\u65CF"},region:"vale",seat:"gulltown",tier:"major",liege:"arryn",sigil:r,colors:["#3b5b7a","#c9a64a"],summary:{en:"The lords of Gulltown, who rule the Vale's great port for the Arryns. Their wealth comes from the city's sea trade with the Free Cities.",zh:"\u6D77\u9E25\u9547\u7684\u9886\u4E3B\uFF0C\u4EE3\u827E\u6797\u5BB6\u65CF\u7EDF\u6CBB\u8C37\u5730\u7684\u5927\u6E2F\u3002\u5BB6\u65CF\u8D22\u5BCC\u6765\u81EA\u8BE5\u57CE\u4E0E\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4E4B\u95F4\u7684\u6D77\u4E0A\u8D38\u6613\u3002"},refs:["affc","twoiaf"]},{id:"baelish",names:{en:"House Baelish",zh:"\u8D1D\u91CC\u5E2D\u5BB6\u65CF"},region:"vale",seat:"baelish-holdfast",tier:"minor",liege:"arryn",sigil:{en:"A grey stone head of the Titan of Braavos on green; Petyr replaces it with a silver mockingbird on green",zh:"\u7EFF\u5E95\u4E0A\u7070\u8272\u7684\u5E03\u62C9\u4F5B\u65AF\u6CF0\u5766\u77F3\u9996\uFF1B\u57F9\u63D0\u5C14\u540E\u6765\u6539\u7528\u7EFF\u5E95\u94F6\u8272\u4EFF\u58F0\u9E1F"},colors:["#3f6b47","#c9cdd0"],summary:{en:"A very small house holding a few stony acres on the Fingers, descended from a Braavosi sellsword who took service in the Vale. Petyr Baelish, fostered at Riverrun, rises from this obscurity to be master of coin and one of the most dangerous men in the realm.",zh:"\u5728\u4E94\u6307\u534A\u5C9B\u4E0A\u53EA\u62E5\u6709\u51E0\u4EA9\u4E71\u77F3\u5730\u7684\u5C0F\u5BB6\u65CF\uFF0C\u5176\u5148\u7956\u662F\u4E00\u540D\u5728\u8C37\u5730\u6548\u529B\u7684\u5E03\u62C9\u4F5B\u65AF\u4F63\u5175\u3002\u5728\u5954\u6D41\u57CE\u957F\u5927\u7684\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u4ECE\u8FD9\u6837\u5BD2\u5FAE\u7684\u51FA\u8EAB\u8D77\u5BB6\uFF0C\u5F53\u4E0A\u4E86\u8D22\u653F\u5927\u81E3\uFF0C\u6210\u4E3A\u738B\u56FD\u6700\u5371\u9669\u7684\u4EBA\u7269\u4E4B\u4E00\u3002"},refs:["agot","acok","asos","affc"],members:[e("petyr-baelish","Petyr Baelish","\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D",{},{en:"Called Littlefinger; master of coin on King Robert's small council, fostered at Riverrun with the Tully children.",zh:"\u4EBA\u79F0\u201C\u5C0F\u6307\u5934\u201D\uFF1B\u52B3\u52C3\u56FD\u738B\u5FA1\u524D\u4F1A\u8BAE\u7684\u8D22\u653F\u5927\u81E3\uFF0C\u5C11\u5E74\u65F6\u4E0E\u5F92\u5229\u5BB6\u7684\u5B69\u5B50\u4EEC\u4E00\u540C\u5728\u5954\u6D41\u57CE\u957F\u5927\u3002"},{fate:{en:'Made Lord of Harrenhal; weds Lysa Arryn, then pushes her through the Moon Door and rules the Vale as Lord Protector, hiding Sansa Stark as his "daughter" Alayne.',zh:"\u53D7\u5C01\u8D6B\u4F26\u5821\u516C\u7235\uFF1B\u5A36\u83B1\u838E\xB7\u827E\u6797\u4E3A\u59BB\uFF0C\u968F\u540E\u5C06\u5979\u63A8\u51FA\u6708\u95E8\uFF0C\u4EE5\u201C\u5B88\u62A4\u8005\u201D\u8EAB\u4EFD\u638C\u63A7\u8C37\u5730\uFF0C\u5E76\u628A\u73CA\u838E\xB7\u53F2\u5854\u514B\u4F2A\u88C5\u6210\u201C\u5973\u513F\u201D\u4E9A\u83B2\u85CF\u5728\u8EAB\u8FB9\u3002"}})]},{id:"hardyng",names:{en:"House Hardyng",zh:"\u54C8\u4E01\u5BB6\u65CF"},region:"vale",tier:"minor",liege:"waynwood",sigil:r,colors:["#e9e4d8","#a3332b"],summary:{en:"A minor Vale house with no named seat, notable because Harrold Hardyng, Lady Waynwood's ward, descends from the Arryns through Jon Arryn's sister Alys.",zh:"\u8C37\u5730\u7684\u5C0F\u5BB6\u65CF\uFF0C\u672A\u6709\u8BB0\u8F7D\u7684\u5C45\u57CE\uFF1B\u4E4B\u6240\u4EE5\u5F15\u4EBA\u6CE8\u76EE\uFF0C\u662F\u56E0\u4E3A\u97E6\u4F0D\u5FB7\u592B\u4EBA\u7684\u88AB\u76D1\u62A4\u4EBA\u54C8\u7F57\u5FB7\xB7\u54C8\u4E01\u7ECF\u7531\u743C\u6069\xB7\u827E\u6797\u4E4B\u59B9\u827E\u4E3D\u4E1D\uFF0C\u627F\u88AD\u4E86\u827E\u6797\u5BB6\u65CF\u7684\u8840\u7EDF\u3002"},refs:["affc","twoiaf"],members:[e("harrold-hardyng","Harrold Hardyng","\u54C8\u7F57\u5FB7\xB7\u54C8\u4E01",{},{en:"Called Harry the Heir; a handsome young knight raised at Ironoaks.",zh:"\u4EBA\u79F0\u201C\u7EE7\u627F\u4EBA\u54C8\u5229\u201D\uFF1B\u5728\u94C1\u6A61\u5821\u957F\u5927\u7684\u82F1\u4FCA\u9752\u5E74\u9A91\u58EB\u3002"},{fate:{en:"Next in line to the Eyrie after Robert Arryn; Petyr Baelish plans to wed him to Sansa Stark (A Feast for Crows).",zh:"\u52B3\u52C3\xB7\u827E\u6797\u4E4B\u540E\u7684\u9E70\u5DE2\u57CE\u7B2C\u4E00\u987A\u4F4D\u7EE7\u627F\u4EBA\uFF1B\u57F9\u63D0\u5C14\xB7\u8D1D\u91CC\u5E2D\u8BA1\u5212\u8BA9\u4ED6\u5A36\u73CA\u838E\xB7\u53F2\u5854\u514B\uFF08\u5377\u56DB\uFF09\u3002"}})]},{id:"moore",names:{en:"House Moore",zh:"\u7A46\u5C14\u5BB6\u65CF"},region:"vale",tier:"minor",liege:"arryn",sigil:r,colors:["#3f6b47","#e9e4d8"],summary:{en:"A minor Vale house best known for Ser Mandon Moore, a cold, expressionless knight of King Robert's Kingsguard.",zh:"\u8C37\u5730\u7684\u5C0F\u5BB6\u65CF\uFF0C\u6700\u51FA\u540D\u7684\u6210\u5458\u662F\u52B3\u52C3\u56FD\u738B\u5FA1\u6797\u94C1\u536B\u4E2D\u51B7\u6F20\u3001\u9762\u65E0\u8868\u60C5\u7684\u66FC\u767B\xB7\u7A46\u5C14\u7235\u58EB\u3002"},refs:["agot","acok"],members:[e("mandon-moore","Mandon Moore","\u66FC\u767B\xB7\u7A46\u5C14",{},{en:"Knight of the Kingsguard.",zh:"\u5FA1\u6797\u94C1\u536B\u9A91\u58EB\u3002"},{fate:{en:"Tries to kill Tyrion during the Battle of the Blackwater and is killed by Podrick Payne (A Clash of Kings).",zh:"\u9ED1\u6C34\u6CB3\u4E4B\u6218\u4E2D\u4F01\u56FE\u6740\u5BB3\u63D0\u5229\u6602\uFF0C\u88AB\u6CE2\u5FB7\u745E\u514B\xB7\u6D3E\u6069\u6240\u6740\uFF08\u5377\u4E8C\uFF09\u3002"}})]},{id:"tollett",names:{en:"House Tollett",zh:"\u6258\u52D2\u7279\u5BB6\u65CF"},region:"vale",seat:"grey-glen",tier:"minor",liege:"arryn",sigil:r,colors:["#7a7e86","#1f1d1b"],summary:{en:"A minor Vale house of Grey Glen. Its famous son is Eddison Tollett, the gloomy, dryly funny brother of the Night's Watch.",zh:"\u7070\u8C37\u7684\u8C37\u5730\u5C0F\u5BB6\u65CF\u3002\u6700\u51FA\u540D\u7684\u5B50\u5F1F\u662F\u5B88\u591C\u4EBA\u4E2D\u9634\u90C1\u800C\u51B7\u5E7D\u9ED8\u7684\u5F1F\u5144\u827E\u8FEA\u68EE\xB7\u6258\u52D2\u7279\u3002"},refs:["asos","twoiaf"],members:[e("eddison-tollett","Eddison Tollett","\u827E\u8FEA\u68EE\xB7\u6258\u52D2\u7279",{},{en:"Called Dolorous Edd; a Night's Watch steward and friend of Jon Snow.",zh:"\u4EBA\u79F0\u201C\u5FE7\u90C1\u7684\u827E\u8FEA\u201D\uFF1B\u5B88\u591C\u4EBA\u4E8B\u52A1\u5B98\uFF0C\u743C\u6069\xB7\u96EA\u8BFA\u7684\u670B\u53CB\u3002"})]},{id:"sunderland",names:{en:"House Sunderland",zh:"\u6851\u5FB7\u5170\u5BB6\u65CF"},region:"vale",tier:"major",liege:"arryn",sigil:r,colors:["#3e6f7a","#e9e4d8"],summary:{en:"Lords of the Three Sisters, overlords of the islands' lesser houses and nominal vassals of the Eyrie. The Sistermen have a long history of rebellion, piracy and shifting loyalties.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u7684\u9886\u4E3B\uFF0C\u7EDF\u8F96\u5C9B\u4E0A\u8BF8\u5C0F\u5BB6\u65CF\uFF0C\u540D\u4E49\u4E0A\u6548\u5FE0\u9E70\u5DE2\u57CE\u3002\u59D0\u59B9\u5C9B\u6C11\u5386\u6765\u53DB\u4E71\u9891\u4ECD\u3001\u52AB\u63A0\u4E3A\u751F\uFF0C\u7ACB\u573A\u53CD\u590D\u65E0\u5E38\u3002"},refs:["adwd","twoiaf"],members:[e("triston-sunderland","Triston Sunderland","\u5D14\u65AF\u987F\xB7\u6851\u5FB7\u5170",{},{en:"Lord of the Three Sisters.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u9886\u4E3B\u3002"})]},{id:"borrell",names:{en:"House Borrell",zh:"\u6CE2\u745E\u5C14\u5BB6\u65CF"},region:"vale",seat:"sisterton",otherSeats:["night-lamp"],tier:"minor",liege:"sunderland",sigil:r,colors:["#5a6670","#e8c95a"],summary:{en:"Lords of Sweetsister, who rule Sisterton and its harbour. Lord Godric Borrell is shrewd about which way the wind is blowing in the War of the Five Kings.",zh:"\u751C\u59D0\u59B9\u5C9B\u7684\u9886\u4E3B\uFF0C\u6CBB\u7406\u59D0\u59B9\u9547\u53CA\u5176\u6E2F\u53E3\u3002\u6208\u5FB7\u745E\xB7\u6CE2\u745E\u5C14\u4F2F\u7235\u5728\u4E94\u738B\u4E4B\u6218\u4E2D\u9887\u61C2\u5F97\u5BA1\u65F6\u5EA6\u52BF\u3002"},refs:["adwd"],members:[e("godric-borrell","Godric Borrell","\u6208\u5FB7\u745E\xB7\u6CE2\u745E\u5C14",{},{en:"Lord of Sweetsister and Shield of Sisterton.",zh:"\u751C\u59D0\u59B9\u5C9B\u4F2F\u7235\uFF0C\u201C\u59D0\u59B9\u9547\u4E4B\u76FE\u201D\u3002"})]},{id:"longthorpe",names:{en:"House Longthorpe",zh:"\u6717\u7D22\u666E\u5BB6\u65CF"},region:"vale",seat:"longsister",tier:"minor",liege:"sunderland",sigil:r,colors:["#4a5a4a","#d9d9d6"],summary:{en:"Lords of Longsister, the largest of the Three Sisters, sworn to the Sunderlands.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u4E2D\u6700\u5927\u7684\u957F\u59D0\u59B9\u5C9B\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u6851\u5FB7\u5170\u5BB6\u65CF\u3002"},refs:["adwd","twoiaf"]},{id:"torrent",names:{en:"House Torrent",zh:"\u6258\u4F26\u7279\u5BB6\u65CF"},region:"vale",seat:"littlesister",tier:"minor",liege:"sunderland",sigil:r,colors:["#3e5f7a","#d9d9d6"],summary:{en:"Lords of Littlesister, the smallest of the Three Sisters, sworn to the Sunderlands.",zh:"\u4E09\u59D0\u59B9\u7FA4\u5C9B\u4E2D\u6700\u5C0F\u7684\u5C0F\u59D0\u59B9\u5C9B\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u6851\u5FB7\u5170\u5BB6\u65CF\u3002"},refs:["adwd","twoiaf"]},{id:"hersy",names:{en:"House Hersy",zh:"\u8D6B\u5E0C\u5BB6\u65CF"},region:"vale",seat:"newkeep",tier:"minor",liege:"arryn",sigil:r,colors:["#7a5a3a","#e9e4d8"],summary:{en:"A lesser house of the Vale, holding Newkeep. It is mentioned in histories and lists of Vale lords rather than in the main story.",zh:"\u8C37\u5730\u7684\u5C0F\u5BB6\u65CF\uFF0C\u636E\u6709\u65B0\u5792\u3002\u5B83\u591A\u89C1\u4E8E\u53F2\u7C4D\u548C\u8C37\u5730\u9886\u4E3B\u540D\u5F55\uFF0C\u5728\u6B63\u4F20\u6545\u4E8B\u4E2D\u51E0\u4E4E\u6CA1\u6709\u620F\u4EFD\u3002"},refs:["twoiaf"]},{id:"lynderly",names:{en:"House Lynderly",zh:"\u6797\u5FB7\u5229\u5BB6\u65CF"},region:"vale",seat:"snakewood",tier:"minor",liege:"arryn",sigil:r,colors:["#3f6b47","#c9a64a"],summary:{en:"Lords of the Snakewood on the Vale's north coast. It appears in lists of the Vale's sworn houses rather than in the main story.",zh:"\u8C37\u5730\u5317\u5CB8\u86C7\u6728\u57CE\u7684\u9886\u4E3B\u3002\u5B83\u591A\u89C1\u4E8E\u8C37\u5730\u5C01\u81E3\u540D\u5F55\uFF0C\u5728\u6B63\u4F20\u6545\u4E8B\u4E2D\u51E0\u4E4E\u6CA1\u6709\u620F\u4EFD\u3002"},refs:["twoiaf"]},{id:"melcolm",names:{en:"House Melcolm",zh:"\u6885\u5C14\u79D1\u59C6\u5BB6\u65CF"},region:"vale",seat:"old-anchor",tier:"minor",liege:"arryn",sigil:r,colors:["#3b5b7a","#e9e4d8"],summary:{en:"Lords of Old Anchor on the Vale's coast, a sworn house of the Arryns known mainly from histories of the region.",zh:"\u8C37\u5730\u6CBF\u6D77\u53E4\u951A\u57CE\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u827E\u6797\u5BB6\u65CF\uFF0C\u4E3B\u8981\u89C1\u4E8E\u8BE5\u5730\u533A\u7684\u53F2\u7C4D\u3002"},refs:["twoiaf"]},{id:"shett",names:{en:"House Shett",zh:"\u96EA\u7279\u5BB6\u65CF"},region:"vale",seat:"gull-tower",tier:"minor",liege:"grafton",sigil:r,colors:["#5a6670","#e9e4d8"],summary:{en:"Holders of the Gull Tower near Gulltown, one of the lesser houses around the Vale's port.",zh:"\u6D77\u9E25\u9547\u9644\u8FD1\u6D77\u9E25\u5854\u7684\u4E3B\u4EBA\uFF0C\u8C37\u5730\u6E2F\u57CE\u5468\u8FB9\u7684\u5C0F\u5BB6\u65CF\u4E4B\u4E00\u3002"},refs:["twoiaf"]},{id:"upcliff",names:{en:"House Upcliff",zh:"\u4E0A\u5D16\u5BB6\u65CF"},region:"vale",seat:"witch-isle",tier:"minor",liege:"arryn",sigil:r,colors:["#4a4a5a","#d9d9d6"],summary:{en:"Lords of Witch Isle in the Bite, sworn to the Arryns.",zh:"\u54AC\u4EBA\u6E7E\u4E2D\u5973\u5DEB\u5C9B\u7684\u9886\u4E3B\uFF0C\u6548\u5FE0\u827E\u6797\u5BB6\u65CF\u3002"},refs:["twoiaf"]},{id:"coldwater",names:{en:"House Coldwater",zh:"\u5BD2\u6C34\u5BB6\u65CF"},region:"vale",seat:"coldwater-burn",tier:"minor",liege:"arryn",sigil:r,colors:["#3e6f7a","#e9e4d8"],summary:{en:"Lords of Coldwater Burn on the Vale's northern shore, known from histories and lists of Vale houses.",zh:"\u8C37\u5730\u5317\u5CB8\u5BD2\u6C34\u6EAA\u57CE\u7684\u9886\u4E3B\uFF0C\u89C1\u4E8E\u53F2\u7C4D\u548C\u8C37\u5730\u5BB6\u65CF\u540D\u5F55\u3002"},refs:["twoiaf"]},{id:"pryor",names:{en:"House Pryor",zh:"\u666E\u745E\u5C14\u5BB6\u65CF"},region:"vale",seat:"pebble",tier:"minor",liege:"arryn",sigil:r,colors:["#7a7e86","#e9e4d8"],summary:{en:"A minor house of Pebble, an island off the Fingers, sworn to the Arryns.",zh:"\u4E94\u6307\u534A\u5C9B\u5916\u6D77\u5375\u77F3\u5C9B\u4E0A\u7684\u5C0F\u5BB6\u65CF\uFF0C\u6548\u5FE0\u827E\u6797\u5BB6\u65CF\u3002"},refs:["twoiaf"]}]};export{h as default};
